amrex::Real W = 0;
amrex::Real sumC = 0;
W += c[0]*1.6731600000000000e+02; // C12H23
W += c[1]*3.1998000000000001e+01; // O2
W += c[2]*2.8053999999999998e+01; // C2H4
W += c[3]*2.7045999999999999e+01; // C2H3
W += c[4]*1.7007000000000001e+01; // OH
