W += c[8]*1.8015000000000001e+01; // H2O
W += c[9]*3.4014000000000003e+01; // H2O2
W += c[10]*2.8009999999999998e+01; // CO
W += c[11]*4.4009000000000000e+01; // CO2
W += c[12]*3.3006000000000000e+01; // HO2
W += c[13]*4.3045000000000002e+01; // CH2CHO
W += c[14]*1.5035000000000000e+01; // CH3
