// species 5: O
Tci[5] = 1.316 * EPS[5] ; 
ai[5] = (5.55 * avogadro * avogadro * EPS[5]*boltzmann * 1e-24 * SIG[5] * SIG[5] * SIG[5] ) / (wt[5] * wt[5]); 
